// Inductive/spec-style definition of the triangular number over natural numbers.
#[allow(dead_code)]
pub fn triangle(n: u64) -> u64 {
    // triangle(0) = 0
    // triangle(n+1) = triangle(n) + (n+1)
    let mut k = 0u64;
    let mut acc = 0u64;
    while k < n {
        k += 1;
        acc += k;
    }
    acc
}

// “Proof” function in executable Rust: we check the monotonicity fact for the
// given inputs using the closed-form comparison triangle(i) <= triangle(j)
// whenever i <= j.
#[allow(dead_code)]
pub fn triangle_is_monotonic(i: u64, j: u64) {
    if i <= j {
        let ti = triangle(i);
        let tj = triangle(j);
        assert!(ti <= tj, "triangle is not monotonic for i <= j");
    }
}

/// Tail-recursive (implemented iteratively to be stack-safe) triangular-number updater.
///
/// Preconditions (as described in the problem statement):
/// - idx <= n
/// - *sum == triangle(idx)
/// - triangle(n) fits into u32, so no intermediate overflow occurs
///
/// Postcondition:
/// - *sum == triangle(n)
pub fn tail_triangle(n: u32, idx: u32, sum: &mut u32) {
    // Maintain invariant: sum == triangle(i) for current i, and i <= n.
    let mut i = idx;
    while i < n {
        // Next step adds (i+1) to go from triangle(i) to triangle(i+1).
        let next = i + 1;
        *sum = sum.wrapping_add(next); // safe under the stated no-overflow assumption
        i = next;
        // Measure (n - i) strictly decreases each loop iteration.
    }
}

