    #[test]
    fn test_monotonic() {
        triangle_is_monotonic(0, 0);
        triangle_is_monotonic(0, 5);
        triangle_is_monotonic(3, 7);
    }

    #[test]
    fn test_tail_triangle() {
        let n = 10u32;
        let mut sum = 0u32; // triangle(0)
        tail_triangle(n, 0, &mut sum);
        assert_eq!(sum as u64, triangle(n as u64));

        // Start from a non-zero index with correct accumulator
        let idx = 4u32;
        let mut sum2 = triangle(idx as u64) as u32;
        tail_triangle(n, idx, &mut sum2);
        assert_eq!(sum2 as u64, triangle(n as u64));
    }
